#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# AI Ledger: deploy to Nebius and finish the hackathon submission.
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. The per-step stages are below the marker. Run from anywhere: ./deploy/wizard.sh

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

cd "$(dirname "${BASH_SOURCE[0]}")/.."   # repo root, so .env and deploy/ resolve
TOTAL_STAGES=10
GH_USER="vishalbanwari26"
IMAGE="ghcr.io/${GH_USER}/ai-ledger:latest"
REPO_URL="https://github.com/${GH_USER}/ai-ledger"

banner "AI Ledger: deploy on Nebius and submit"

# ── 1. Tools ───────────────────────────────────────────────────────────────
stage "Check your tools"
say "Everything below needs these on your machine."
missing=0
for tool in docker gh curl jq nebius; do
  if command -v "$tool" >/dev/null 2>&1; then say "$(printf '✓ %s' "$tool")"; else warn "missing: $tool"; missing=1; fi
done
if command -v docker >/dev/null 2>&1 && ! docker info >/dev/null 2>&1; then
  warn "Docker is installed but not running. Start Docker Desktop and wait for it to say 'running'."; missing=1
fi
if command -v gh >/dev/null 2>&1 && ! gh auth status >/dev/null 2>&1; then
  warn "gh is not logged in. In another terminal run: gh auth login"; missing=1
fi
if ! command -v nebius >/dev/null 2>&1; then
  step "Install the Nebius CLI: https://docs.nebius.com/cli"
  open_url "https://docs.nebius.com/cli"
fi
if command -v jq >/dev/null 2>&1; then :; else step "Install jq: brew install jq"; fi
if (( missing )); then
  pause "Fix the items above, then press Enter to re-check (or Ctrl-C and re-run)."
  command -v docker >/dev/null 2>&1 && docker info >/dev/null 2>&1 || { warn "Docker still not running. Fix it and re-run the wizard."; exit 1; }
  command -v nebius >/dev/null 2>&1 || { warn "nebius CLI still missing. Install it and re-run the wizard."; exit 1; }
fi
say "Tools are ready."
pause

# ── 2. Nebius CLI login ────────────────────────────────────────────────────
stage "Log in to the Nebius CLI"
say "One-time setup so the CLI can create your endpoint."
if nebius ai endpoint list >/dev/null 2>&1; then
  say "✓ The CLI is already configured and can list endpoints."
else
  step "Next the wizard runs: nebius profile create"
  step "Follow its prompts and the browser window it opens. Pick your project and region when asked."
  pause "Press Enter to run it."
  nebius profile create || warn "profile create reported a problem, and the check below will tell you"
  if nebius ai endpoint list >/dev/null 2>&1; then say "✓ The CLI can now list endpoints."
  else warn "The CLI still cannot list endpoints. Check your project and permissions in the Nebius console, then re-run."; exit 1; fi
fi
pause

# ── 3. Demo-only Token Factory key ─────────────────────────────────────────
stage "Create a demo-only Token Factory key"
say "Do not reuse another project's key. This one lives in the public endpoint's settings, so you will delete it after judging."
open_url "https://tokenfactory.nebius.com/"
step "Open the API keys area, create a key named: ai-ledger-demo"
step "Copy it now: it is usually shown only once."
ask_secret NEBIUS_API_KEY "Paste the new key:"
say "Checking it against Token Factory..."
models_file=$(mktemp)
code=$(curl -s -o "$models_file" -w '%{http_code}' -H "Authorization: Bearer ${NEBIUS_API_KEY}" "https://api.tokenfactory.nebius.com/v1/models" || echo 000)
if [[ "$code" == "200" ]] && grep -qi 'nemotron' "$models_file"; then
  say "✓ The key works and the account lists NVIDIA Nemotron models."
else
  warn "The check failed (HTTP $code). Nemotron models listed: $(grep -ci nemotron "$models_file" 2>/dev/null || echo 0)."
  warn "Re-run the wizard with a fresh key, or confirm Nemotron is enabled for your account."; rm -f "$models_file"; exit 1
fi
rm -f "$models_file"
write_env NEBIUS_API_KEY "$NEBIUS_API_KEY"
pause

# ── 4. GitHub package login ────────────────────────────────────────────────
stage "Let Docker push to GitHub's container registry"
say "Nebius pulls the image from here. A classic token with the write:packages permission is enough."
open_url "https://github.com/settings/tokens/new?scopes=write:packages&description=ai-ledger-ghcr"
step "Set an expiry of 7 days, click Generate token, copy it."
ask_secret GITHUB_PAT "Paste the token:"
printf '%s' "$GITHUB_PAT" | docker login ghcr.io -u "$GH_USER" --password-stdin
unset GITHUB_PAT
say "✓ Docker is logged in to ghcr.io (the token was not saved anywhere)."
pause

# ── 5. Build and push ──────────────────────────────────────────────────────
stage "Build the image and push it"
say "This builds for Nebius's amd64 CPUs and uploads to: $IMAGE"
note "First build can take several minutes. Apple Silicon builds for amd64 under emulation."
if confirm "Build and push now?"; then
  IMAGE="$IMAGE" STEP=push ./deploy/deploy.sh
  say "✓ Image pushed."
else
  warn "Skipped. Re-run the wizard when ready."; exit 1
fi
pause

# ── 6. Make the package public ─────────────────────────────────────────────
stage "Make the image public so Nebius can pull it"
open_url "https://github.com/users/${GH_USER}/packages/container/ai-ledger/settings"
step "Scroll to Danger Zone → Change package visibility → Public."
step "Type the package name (ai-ledger) to confirm."
pause "Press Enter once it says Public."
docker logout ghcr.io >/dev/null 2>&1 || true
say "Checking with an anonymous pull request..."
if docker manifest inspect "$IMAGE" >/dev/null 2>&1; then
  say "✓ The image is publicly pullable."
else
  warn "The image is still private (or the push did not finish). Fix it in the settings page, then re-run the wizard (it skips values it already saved)."; exit 1
fi
pause

# ── 7. Create the endpoint ─────────────────────────────────────────────────
stage "Create the Nebius Serverless Endpoint"
say "CPU container, port 8080, public URL. The models stay on Token Factory, so no GPU is needed."
note "If the CLI rejects the CPU preset, list valid ones (try: nebius compute platform list) and edit deploy/deploy.sh."
note "If --env is rejected, create the endpoint in the console with the same image and add NEBIUS_API_KEY there."
if confirm "Create the endpoint now?"; then
  out=$(IMAGE="$IMAGE" STEP=create NEBIUS_API_KEY="$NEBIUS_API_KEY" ./deploy/deploy.sh 2>&1) || { printf '%s\n' "$out"; warn "Endpoint creation failed. Read the message above."; exit 1; }
  printf '%s\n' "$out" | tail -6
  DEMO_URL=$(printf '%s\n' "$out" | sed -n 's/^ENDPOINT_URL=//p' | tail -1)
else
  warn "Skipped. Re-run when ready."; exit 1
fi
if [[ -z "${DEMO_URL:-}" ]]; then
  warn "Could not read the URL from the output."
  step "Copy the HTTPS address from the endpoint's details page in the Nebius console."
  ask DEMO_URL "Paste the endpoint URL:"
fi
write_env DEMO_URL "$DEMO_URL"
pause

# ── 8. Verify the live app ─────────────────────────────────────────────────
stage "Check the live demo"
say "Waiting for the endpoint to answer (a new container can take a minute or two)..."
ok=0
for i in $(seq 1 24); do
  if [[ "$(curl -s -o /dev/null -w '%{http_code}' "${DEMO_URL%/}/healthz" || echo 000)" == "200" ]]; then ok=1; break; fi
  printf '  .'; sleep 10
done
printf '\n'
(( ok )) || { warn "The app did not answer within 4 minutes. Check the endpoint's logs in the Nebius console."; exit 1; }
say "✓ /healthz answers."
people=$(curl -s "${DEMO_URL%/}/api/report" | jq -r '.summary.company.headcount // empty')
[[ "$people" == "1900" ]] && say "✓ The dashboard loads the demo company ($people people)." || { warn "Unexpected report: $people"; exit 1; }
say "Asking the analyst a question (this calls Nemotron on Token Factory)..."
ans=$(curl -s -m 120 -X POST "${DEMO_URL%/}/api/ask" -H 'Content-Type: application/json' -d '{"question":"Where is most of the recoverable spend?"}')
tools=$(printf '%s' "$ans" | jq -r '[.evidence[].tool] | join(", ")' 2>/dev/null || true)
model=$(printf '%s' "$ans" | jq -r '.model // empty' 2>/dev/null || true)
if [[ -n "$tools" && -n "$model" ]]; then say "✓ Answered by $model using: $tools"; else warn "The analyst did not answer: $(printf '%s' "$ans" | head -c 300)"; exit 1; fi
open_url "$DEMO_URL"
step "Open that URL in a private window too. It must load with no login."
step "Click Generate in the Overview, and ask one question in the Ask tab."
confirm "Everything works in the browser?" || { warn "Fix it before going on."; exit 1; }

# ── 9. Video ───────────────────────────────────────────────────────────────
stage "Record and upload the video (do this today, uploads are slow)"
say "Under 3:00, public on YouTube, shows the app working and says how Nebius and NVIDIA are used."
step "Follow docs/demo-script.md. Cut from the bottom of its list if you run over."
step "Do not show a terminal with a key in it."
open_url "https://studio.youtube.com/"
step "Upload, set visibility to Public, copy the video link."
ask YOUTUBE_URL "Paste the YouTube link:"
if [[ "$(curl -s -o /dev/null -w '%{http_code}' "https://www.youtube.com/oembed?url=${YOUTUBE_URL}&format=json" || echo 000)" == "200" ]]; then
  say "✓ YouTube reports the video as public."
else
  warn "YouTube does not show it as public yet (processing, or visibility is not Public)."
  confirm "Continue anyway and fix it before submitting?" || exit 1
fi
confirm "Is the video under 3:00?" || { warn "Cut it down and re-upload. Judges stop at 3:00."; exit 1; }
write_env YOUTUBE_URL "$YOUTUBE_URL"
pause

# ── 10. Devpost form ───────────────────────────────────────────────────────
stage "Fill in the Devpost submission"
open_url "https://nebiusglobalaihackathon.devpost.com/"
say "Ready to paste (text is in docs/devpost-submission.md):"
note "  Track:        Best Apps and Agents"
note "  Repo:         $REPO_URL"
note "  Demo URL:     $DEMO_URL"
note "  Video:        $YOUTUBE_URL"
step "Paste the description sections and the feedback from docs/devpost-submission.md. Edit the feedback to match what you saw."
step "Add every teammate to the form, and tell them to accept the invitation."
step "Submit at least a few hours before Friday 30 October, 10:00 AM PT. After the deadline nothing may be edited."
confirm "Submitted?" || warn "Not submitted yet. The deadline is Friday 30 October, 10:00 AM PT."
say "After judging: delete the endpoint and the demo key (commands are in docs/deploy-checklist.md)."

finish
}

run_wizard "$@"; exit
